// TH16 v1.00a Stage 2 midboss wave (th16_s2_w06)
// Source: st02.ecl.txt MainSub05:1086-1127 (entry), plus dependencies
//   MainSub05b:1129-1135, GirlC02:412-435, GirlC02_at:437-486,
//   Phantom01:1201-1221, Phantom01B/R:1223-1239, Phantom01_at:1241-1274.
// Planes spawn as two mirrored Phantom01 flights (9 pairs each, 40f then 2x9, 35f),
// while MainSub05b creates the GirlC02 pair at source +240.

const TH16_BALL2: int = 432;      // source etSprite(0, 5, 2)
const TH16_RING_BALL2: int = 464; // source etSprite(0, 7, 4)

const TIME_LIMIT: int = 2724;
const OPENING_BUFFER: int = 120;

// moveEllipseRel(F0, 0.034906585, 40, 0, ABS_ANGLE=pi/2, 0):
// s=0 => REL offset is 40*sin(theta-beta)*(-sin beta, cos beta) with beta=pi/2,
// i.e. a purely horizontal 40*cos(theta) wobble; theta advances 2deg/frame.
const ELLIPSE_R: fx = 40fx;
const ELLIPSE_W: int = 364;       // 0.034906585 rad = 2 deg

// GirlC02_at EX: type 2 ANIM a=1 (spawn shift -4*velocity) then type 4 ACCEL
// a=230, r=0.01 (Hard 0.02), s=-999999 keeps the bullet direction.
xformdef GIRL_ACCEL(gx: fx, gy: fx) {
    @230 set_gravity(gx, gy);
    set_gravity(0fx, 0fx);
}

// Phantom01_at volley: etAim(0,0), etCountD ways=1 / layers E1 N1 H2 L3,
// etSpeedD E1.5 N2.0 H3.0->1.0 L4.0->1.0, etAngle(0,0). ANIM a=1 shifts each
// bullet by -4*velocity along its firing angle.
sub phantom_volley() {
    var aim: angle = aim_player();
    var m: int = 1;
    var s0: fx = 1.5fx;
    var s1: fx = 1fx;
    var r: int = global(GVAR_RANK);
    if r == 1 { s0 = 2fx; s1 = 0.8fx; }
    if r == 2 { m = 2; s0 = 3fx; s1 = 1fx; }
    if r == 3 { m = 3; s0 = 4fx; s1 = 1fx; }
    var ca: fx = cos(aim);
    var sa: fx = sin(aim);
    for q in 0..m {
        var v: fx = s0;
        if m > 1 { v = s0 + (s1 - s0) * (q as fx) / ((m - 1) as fx); }
        var sx: fx = $self_x - 4fx * (v * ca);
        var sy: fx = $self_y - 4fx * (v * sa);
        _ = fire(TH16_BALL2, 2, sx, sy, v, aim, none, none);
    }
}

// Phantom01 body. phase_bam is the inherited F0 (0, +-20deg ...); mirror is the
// enmCreateM child mirror bit reflected onto world-space movement.
async sub phantom(phase_bam: int, mirror: int) {
    set_invuln(65535);
    set_hitbox(8fx);   // setHitbox(16,16) -> r=8
    set_hurtbox(14fx); // setHurtbox(28,28) -> r=14

    // Ellipse setter applies its current phase immediately.
    move_to(0, $self_x + ELLIPSE_R * cos(phase_bam as angle), $self_y, EASE_LINEAR);

    // Phantom01_at: wait(10 + RAND%60), Easy +50, then volleys per rank.
    var w: int = 10 + rand(60);
    var rank: int = global(GVAR_RANK);
    var volleys: int = 3;
    var interval: int = 50;
    if rank == 0 { w = w + 50; volleys = 1; interval = 240; }
    if rank == 1 { volleys = 2; interval = 240; }
    if rank == 2 { volleys = 2; interval = 120; }

    var j: int = 0;
    var next_fire: int = w;
    var left: int = volleys;
    loop {
        if j == next_fire && left > 0 {
            phantom_volley();
            left = left - 1;
            next_fire = next_fire + interval;
        }
        // arm source movement tick k = j+1 (engine integrates in phase 5).
        var k: int = j + 1;
        var v: fx = 1fx;
        if k <= 120 {
            // moveVelTime(120, 3, pi/2, 1.0): quartic-in speed 0.5 -> 1.0
            var u: fx = (k as fx) / 120fx;
            var u4: fx = u * u * u * u;
            v = 0.5fx + 0.5fx * u4;
        }
        var ang: angle = 90deg;
        if k > 240 && k <= 360 {
            // moveVelTime(120, 3, -pi/2, 1.0): shortest-arc rule keeps the +pi
            // turn (90deg -> 270deg), quartic-in.
            var ua: fx = ((k - 240) as fx) / 120fx;
            var ua4: fx = ua * ua * ua * ua;
            var half: int = (ua4 * 16384fx) as int;
            ang = 90deg + ((half * 2) as angle);
        } else if k > 360 {
            ang = 270deg;
        }
        var dx: fx = v * cos(ang);
        var dy: fx = v * sin(ang);
        if mirror != 0 { dx = 0fx - dx; }
        var rel_now: fx = ELLIPSE_R * cos((phase_bam + k * ELLIPSE_W) as angle);
        var rel_prev: fx = ELLIPSE_R * cos((phase_bam + (k - 1) * ELLIPSE_W) as angle);
        dx = dx + rel_now - rel_prev;
        move_vel_xy(0, dx, dy, EASE_LINEAR);
        j = j + 1;
        wait(1);
        // source flagClear(12) at script +480 lets the plane leave; retire once
        // it is well above the field instead of a permanent offscreen entity.
        if $self_y < -64fx { return; }
    }
}

// GirlC02_at: etAim(0,3) with alpha=ANGLE_PLAYER per volley, count E8 N24 H36
// L24, etAngle(0,0)/(0,10deg) (delta unused with 1 layer), speed 0.3.
async sub girl_at() {
    wait(60);
    var rank: int = global(GVAR_RANK);
    var n: int = 24;
    var accel: fx = 0.01fx;
    var volleys: int = 3;
    var interval: int = 60;
    if rank == 0 { n = 8; volleys = 2; interval = 130; }
    if rank == 1 { interval = 130; }
    if rank == 2 { n = 36; accel = 0.02fx; interval = 80; }
    for vol in 0..volleys {
        var aim: angle = aim_player();
        for i in 0..n {
            var a: angle = aim + (((i * 65536) / n) as angle);
            var ca: fx = cos(a);
            var sa: fx = sin(a);
            var sx: fx = $self_x - 1.2fx * ca;
            var sy: fx = $self_y - 1.2fx * sa;
            _ = fire(TH16_RING_BALL2, 4, sx, sy, 0.3fx, a,
                     GIRL_ACCEL(accel * ca, accel * sa), none);
        }
        wait(interval);
    }
}

// GirlC02 body: moveVel(-0.19634955, 2.0), moveVelTime(80,1,-999999,0.1),
// wait(80), moveVelTime(70,1,0.0,0.3), wait(70) then the source idle loop.
async sub girl(mirror: int) {
    set_invuln(65535);
    set_hitbox(12fx);   // setHitbox(24,24) -> r=12
    set_hurtbox(16fx);  // setHurtbox(32,32) -> r=16
    var dir: angle = -11.25deg; // -0.19634955 rad
    var after: angle = 0deg;
    if mirror != 0 {
        dir = 191.25deg;        // mirrored write point: reflect across x
        after = 180deg;
    }
    move_vel(0, dir, 2fx, EASE_LINEAR);
    move_speed(80, 0.1fx, EASE_QUAD_IN); // keep heading, source mode 1
    spawn girl_at();
    wait(80);
    move_vel(70, after, 0.3fx, EASE_QUAD_IN);
    wait(70);
    loop { wait(1000); }
}

async sub girl_pair() {
    wait(240); // MainSub05b
    _ = spawn_enemy(-224fx, 240fx, 1500, 0, 1000, 0, girl(0));
    _ = spawn_enemy(224fx, 240fx, 1500, 0, 1000, 0, girl(1));
}

async sub pattern() {
    wait(OPENING_BUFFER);
    spawn girl_pair();
    wait(2);
    // MainSub05_192/336: 9 pairs, A=16..144, F0=+20deg steps, 40f apart.
    var phase: int = 0;
    for i in 0..9 {
        var a: fx = (16 * (i + 1)) as fx;
        _ = spawn_enemy(a, -24fx, 100, 0, 1000, 0, phantom(phase, 0));
        _ = spawn_enemy(0fx - a, -24fx, 100, 0, 1000, 0, phantom(phase, 1));
        phase = phase + 3641;
        wait(40);
    }
    // MainSub05_800/944: two 9-pair flights, F0 reset to 0 then -20deg steps.
    for d in 0..2 {
        phase = 0;
        for i2 in 0..9 {
            var a2: fx = (16 * (i2 + 1)) as fx;
            _ = spawn_enemy(a2, -24fx, 100, 0, 1000, 0, phantom(phase, 0));
            _ = spawn_enemy(0fx - a2, -24fx, 100, 0, 1000, 0, phantom(phase, 1));
            phase = phase - 3641;
            wait(35);
        }
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
